# frozen_string_literal: true
# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Timekeeping::Handoff::SourceIntentsFile do
  # "Deleting a terminal intent or changing its `desired_entry_ids` after checkpoint capture cannot produce a
  # source-versus-current difference."
  # A malformed baseline read as empty or partial would make reconcile compare against the wrong rows, so any
  # text that is not a well-typed intents file must be refused.
  it "refuses source intents text with a wrongly typed or missing column instead of returning a partial baseline" do
    row = {
      "id" => 7, "company_id" => 11, "invoice_id" => 101,
      "operation_id" => "00000000-0000-0000-0000-000000000007", "generation" => 1,
      "desired_entry_ids" => [3, 4], "disposition" => "active", "state" => "failed",
      "created_at" => Time.utc(2026, 10, 30, 12, 0, 0, 654_321), "finished_at" => nil
    }
    text = described_class.dump([row])
    expect(described_class.load(text)).to eq([row])

    wrong_type = text.sub(/"desired_entry_ids".*?\]/m) { |match| match.gsub(/\d+/) { |digit| "\"#{digit}\"" } }
    expect(wrong_type).not_to eq(text)

    [wrong_type, text[0, text.length - 3], "", "null", JSON.generate("rows" => "nope")].each do |bad|
      expect { described_class.load(bad) }.to raise_error(described_class::Unreadable)
    end

    without_state = described_class.dump([row]).sub("\"state\"", "\"status\"")
    expect { described_class.load(without_state) }.to raise_error(described_class::Unreadable)
  end
end
